use std::collections::HashMap;

fn main() {
    let key = String::from("id");
    let mut m = HashMap::new();
    m.insert(key, 7);
    println!("{}", key);
}

use std::collections::BTreeMap;

fn main() {
    let mut m = BTreeMap::new();
    for w in "to be or not to be".split_whitespace() {
        *m.entry(w).or_insert(0) += 1;
    }
    let top = m.iter().filter(|(_, n)| **n > 1).count();
    println!("{} {}", m.len(), top);
    println!("{:?}", m.get("be"));
}
